import sys

def is_composite(n: int) -> bool:
    if n < 4:
        return False
    if n % 2 == 0:
        return True
    if n % 3 == 0:
        return True
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i+2) == 0:
            return True
        i += 6
    return False

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])

    # Try small composites for b
    small_composites = [4,6,8,9,10,12,14,15,16,18,20,21,22,24,25,26,27,28,30]
    for b in small_composites:
        a = b + n
        if is_composite(a) and is_composite(b):
            print(a, b)
            return

    # Try b near n (so a = b+n near 2n)
    b = n
    while b > 0:
        if is_composite(b):
            a = b + n
            if is_composite(a):
                print(a, b)
                return
        b -= 1

if __name__ == "__main__":
    main()
